#include <unordered_map>
#include <algorithm>

class Solution {
    std::unordered_map<int, int> memo;
public:
    int minDays(int n) {
        if (n <= 1) return n;
        if (memo.count(n)) return memo[n];
        int res = 1 + std::min(n % 2 + minDays(n / 2), n % 3 + minDays(n / 3));
        return memo[n] = res;
    }
};

import java.util.*;

class Solution {
    Map<Integer, Integer> memo = new HashMap<>();
    public int minDays(int n) {
        if (n <= 1) return n;
        if (memo.containsKey(n)) return memo.get(n);
        int res = 1 + Math.min(n % 2 + minDays(n / 2), n % 3 + minDays(n / 3));
        memo.put(n, res);
        return res;
    }
}

var minDays = function(n) {
    const memo = new Map();
    memo.set(0, 0);
    memo.set(1, 1);
    function dp(x) {
        if (memo.has(x)) return memo.get(x);
        const res = 1 + Math.min(x % 2 + dp(Math.floor(x / 2)), x % 3 + dp(Math.floor(x / 3)));
        memo.set(x, res);
        return res;
    }
    return dp(n);
};
